int n = 4, t[8] = {0, 1, 2, 1, 5, 2, 9, 1};
void update(int i, int v) {
    i += n;
    t[i] = v;
    for (; i > 1; i >>= 1)
        t[i >> 1] = min(t[i], t[i ^ 1]);
}
int main() { update(1, 8); cout << t[2] << ' ' << t[1]; }

int query(int l, int r) {
    int m = INT_MAX;
    for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
        if (l & 1) m = min(m, t[l++]);
        if (r & 1) m = min(m, t[--r]);
    }
    return m;
}
